Ακολουθεί κώδικας που εφαρμόζει ανίχνευση ακμών Canny με τη βιβλιοθήκη OpenCV:

#include <opencv2/opencv.hpp>
#include <iostream>

cv::Mat applyCannyEdgeDetection(const cv::Mat& inputImage, double threshold1 = 50.0, double threshold2 = 150.0)
{
    // Μετατροπή της εικόνας εισόδου σε κλίμακα του γκρι
    cv::Mat grayImage;
    cv::cvtColor(inputImage, grayImage, cv::COLOR_BGR2GRAY);

    // Θόλωση Gauss για μείωση του θορύβου
    cv::Mat blurredImage;
    cv::GaussianBlur(grayImage, blurredImage, cv::Size(5, 5), 0);

    // Εφαρμογή της ανίχνευσης ακμών Canny
    cv::Mat edges;
    cv::Canny(blurredImage, edges, threshold1, threshold2);

    return edges;
}

int main()
{
    // Φόρτωση της εικόνας εισόδου
    cv::Mat inputImage = cv::imread("input.jpg");

    if (inputImage.empty()) {
        std::cerr << "Η φόρτωση της εικόνας εισόδου απέτυχε" << std::endl;
        return 1;
    }

    // Εφαρμογή της ανίχνευσης ακμών Canny στην εικόνα εισόδου
    cv::Mat outputImage = applyCannyEdgeDetection(inputImage);

    // Εμφάνιση της εικόνας εισόδου και του αποτελέσματος
    cv::imshow("Input Image", inputImage);
    cv::imshow("Canny Edge Detection", outputImage);
    cv::waitKey(0);

    return 0;
}

Η συνάρτηση applyCannyEdgeDetection δέχεται μια εικόνα και επιστρέφει την εικόνα των ακμών: τη μετατρέπει σε κλίμακα του γκρι, εξομαλύνει τον θόρυβο με φίλτρο Gauss και εφαρμόζει τη cv::Canny. Τα δύο κατώφλια είναι παράμετροι με προεπιλεγμένες τιμές, ώστε να μπορείς να καλέσεις τη συνάρτηση δίνοντας μόνο την εικόνα, όπως ζήτησες, αλλά και να τα ρυθμίσεις αν χρειαστεί: χαμηλότερες τιμές δίνουν περισσότερες ακμές, υψηλότερες λιγότερες.

Για να μεταγλωττιστεί, χρειάζεται εγκατεστημένη την OpenCV και σύνδεση με τις βιβλιοθήκες της, π.χ. g++ main.cpp -o main `pkg-config --cflags --libs opencv4`.
